public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    boolean escaping = false;
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\' && !escaping) {
            escaping = true;
        } else {
            if (escaping) {
                if (ch == 'n') {
                    sb.append('\n');
                } else if (ch == 't') {
                    sb.append('\t');
                } else if (ch == 'r') {
                    sb.append('\r');
                } else if (ch == 'f') {
                    sb.append('\f');
                } else if (ch == 'b') {
                    sb.append('\b');
                } else if (ch == '\\') {
                    sb.append('\\');
                } else if (ch == '"') {
                    sb.append('"');
                } else if (ch == '\'') {
                    sb.append('\'');
                } else {
                    throw new IllegalArgumentException("Invalid escape character '" + ch + "' at index " + i);
                }
                escaping = false;
            } else {
                sb.append(ch);
            }
        }
    }
    if (escaping) {
        throw new IllegalArgumentException("Last character is an escape character");
    }
    return sb.toString();
}

