void removeUnusedNodes() {
    int count = 0;
    Node root = this.root;
    if (root == null) {
        return count;
    }
    Stack<Node> stack = new Stack<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Node current = stack.pop();
        if (current.isLeaf()) {
            if (current.isActive()) {
                count++;
            } else {
                Node parent = current.getParent();
                if (parent != null) {
                    parent.removeChild(current);
                }
            }
        } else {
            for (Node child : current.getChildren()) {
                stack.push(child);
            }
        }
    }
    return count;
}

