    }

    // Get the constant pool entry at the specified index
    CONSTANT_Utf8_info constantPoolEntry = (CONSTANT_Utf8_info) constantPool.get(constantPoolEntryIndex);

    // Check if the constant pool entry is a CONSTANT_Utf8
    if (constantPoolEntry.getTag() != CONSTANT_Utf8) {
        throw new IllegalArgumentException("CONSTANT_Utf8 entry expected, but found " + constantPoolEntry.getTag());
    }

    // Get the length of the string in the constant pool entry
    int length = constantPoolEntry.getLength();

    // Check if the input buffer has enough capacity to hold the string
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("Insufficient buffer capacity to hold the string");
    }

    // Copy the string from the constant pool entry to the input buffer
    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) constantPoolEntry.getBytes()[i];
    }

    return new String(charBuffer, 0, length);
